/**
 * Validates every tour data file against the generated JSON Schemas and exits
 * non-zero on any problem. Catches unsupported/misspelled properties, invalid
 * enum values (stop `type`, `mapProvider`, per-provider `mapStyleId`, …) and missing
 * required fields per stop type.
 *
 * Run directly (`bun run validate`) or as the pre-step of `bun run build`.
 * Schemas come from packages/schema (generated by `bun run schema`) — run it
 * first if you changed the types there.
 */
import { Glob } from 'bun';
import { resolve, dirname, relative } from 'node:path';
import { fileURLToPath } from 'node:url';
import {
  validateTourFile,
  validateTourMetadata,
  validateAppConfig,
} from '@audioguidekit/schema';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');

// Only the source of truth — public/data/tour is generated from this by the
// vite-config sync plugin, so validating it too would double-report errors.
const tourFiles = [
  ...new Glob('src/data/tour/**/*.json').scanSync({ cwd: root, absolute: true }),
];

let failed = 0;

for (const file of tourFiles.sort()) {
  const rel = relative(root, file);
  const isMeta = file.endsWith('/metadata.json');
  const isApp = file.endsWith('/app.json');
  const data = require(file);
  const result = (isApp ? validateAppConfig : isMeta ? validateTourMetadata : validateTourFile)(data);

  if (result.valid) {
    // Semantic check the schema can't express: `totalStops` is the denominator
    // of the player's progress percentage, and only an audio track reaching
    // 100% ever marks a stop complete (App.tsx handleAudioProgress →
    // markStopCompleted). Counting every stop leaves the progress bar
    // permanently short of 100% on any tour with a non-audio stop — silently.
    const audioStops = !isMeta && !isApp
      ? (data.stops ?? []).filter((s: any) => s?.type === 'audio').length
      : null;
    if (audioStops !== null && data.totalStops !== audioStops) {
      failed++;
      console.error(`\n✗ ${rel}`);
      console.error(
        `    totalStops is ${data.totalStops} but the tour has ${audioStops} audio stop(s).` +
          ` totalStops counts audio stops only — see docs/adding-tours.md.`
      );
      continue;
    }
    console.log(`✓ ${rel}`);
    continue;
  }

  failed++;
  console.error(`\n✗ ${rel}`);
  for (const err of result.errors) {
    console.error(`    ${err}`);
  }
}

if (failed > 0) {
  console.error(`\n${failed} file(s) failed validation.`);
  process.exit(1);
}
console.log(`\nAll ${tourFiles.length} tour file(s) valid.`);
